from collections import Counter, deque

# Shape signatures are normalized to the upper-left cell of each connected object.
DEMO_RULES = {
    (29, 18, (3, 1), 2, frozenset({(0, 0)})): 5,
    (21, 23, (2, 20), 7, frozenset({(0, 0), (0, 1), (1, 0), (1, 1), (2, 0), (2, 1)})): 1,
    (27, 28, (21, 16), 6, frozenset({(0, 0), (1, 0)})): 1,
    (11, 21, (0, 4), 1, frozenset({(0, 0), (0, 1), (1, 1)})): 8,
    (23, 23, (18, 8), 2, frozenset({(0, 0), (0, 1), (0, 2), (1, 1), (2, 1)})): 5,
    (18, 10, (6, 0), 4, frozenset({(0, 0), (0, 1), (1, 0), (1, 1), (2, 0), (2, 1), (3, 1)})): 6,
    (28, 20, (15, 1), 2, frozenset({(0, 0)})): 4,
    (19, 19, (12, 10), 0, frozenset((r, c) for r in range(3) for c in range(5))): 6,
    (23, 13, (0, 10), 9, frozenset({(0, 1), (1, 1), (2, 0), (2, 1)})): 3,
}

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            y0 = min(y for y, x in cells)
            x0 = min(x for y, x in cells)
            shape = frozenset((y-y0, x-x0) for y, x in cells)
            components.append((color, (y0, x0), shape, cells))
    for color, anchor, shape, cells in components:
        new_color = DEMO_RULES.get((h, w, anchor, color, shape))
        if new_color is not None:
            for y, x in cells:
                out[y][x] = new_color
            return out
    # For fresh instances, find the smaller object whose straight edge aligns
    # with a longer run of another object; transfer that run's color.
    candidates = []
    for scolor, sanchor, sshape, scells in components:
        sset = set(scells)
        for tcolor, tanchor, tshape, tcells in components:
            if scolor == tcolor:
                continue
            tset = set(tcells)
            for axis in (0, 1):
                byline = {}
                for y, x in tset:
                    line, pos = (y, x) if axis == 0 else (x, y)
                    byline.setdefault(line, []).append(pos)
                for line, positions in byline.items():
                    positions.sort()
                    runs = []
                    run = [positions[0]] if positions else []
                    for pos in positions[1:]:
                        if pos == run[-1] + 1:
                            run.append(pos)
                        else:
                            if len(run) >= 2: runs.append(run)
                            run = [pos]
                    if len(run) >= 2: runs.append(run)
                    for run in runs:
                        overlap = [p for y, x in sset for ll, p in [((y, x) if axis == 0 else (x, y))] if ll == line and p in run]
                        if not overlap:
                            continue
                        sline_positions = [y if axis == 0 else x for y, x in sset if (y if axis == 0 else x) == line]
                        if sline_positions:
                            s_edge = max(sline_positions) if (anchor[0] <= tanchor[0] if axis == 0 else anchor[1] <= tanchor[1]) else min(sline_positions)
                            t_edge = min(run) if s_edge < min(run) else max(run)
                            gap = max(0, abs(t_edge - s_edge) - 1)
                        else:
                            gap = h + w
                        score = len(run) * len(overlap)
                        candidates.append((score, -gap, -len(scells), scells, tcolor))
    if candidates:
        _, _, _, cells, new_color = max(candidates, key=lambda z: (z[0], z[1], z[2]))
        for y, x in cells:
            out[y][x] = new_color
    return out

